INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 21, 'theory', 'Quiz: lifetimes and smart pointers');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 0, 'What does Rc::clone(&a) do?', '["Copies the data into a new area of the heap", "Moves ownership and zeroes a", "Increases the strong counter; the data stays shared", "Creates a weak reference"]', 2, 'Cloning an Rc is cheap: only the counter changes. The value is destroyed when the counter reaches zero.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 1, 'When does a program with RefCell panic?', '["When borrow() is called on an empty value", "When two mutable references exist at once, or a mutable and a shared one", "When the value is too big", "Never"]', 1, 'RefCell checks the borrowing rules at run time: a violation gives BorrowMutError. try_borrow_mut() returns Err instead of panicking.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 2, 'Why is the reference to the parent in a tree made Weak and not Rc?', '["To avoid an Rc cycle that keeps the counters from reaching zero", "To save memory", "So that the parent can be changed", "Because Weak is faster"]', 0, 'The parent holds its children through strong references, and the child holds the parent through a weak one. Then there is no cycle, and the nodes get freed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 3, 'How does Arc differ from Rc?', '["It doesn''t", "Arc keeps the value on the stack", "The Arc counter changes with atomic instructions, so it can be shared between threads, but it is slower", "Rc can be sent to threads"]', 2, 'Rc does not implement Send and will not go to another thread. Arc pays for atomicity with speed and cache traffic.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 21, 4, 'What happens with fn pick(a: &str, b: &str) -> &str without lifetime labels?', '["Returns a reference to a", "A compile error: it is unclear which argument the result is tied to", "Returns a reference to b", "Returns a new string"]', 1, 'The elision rules do not allow a choice between two inputs. A label is needed: fn pick<''a>(a: &''a str, b: &''a str) -> &''a str.');
